import SwiftUI

struct ShiftsView: View { @EnvironmentObject var store: AppStore; @State private var showAdd = false; @State private var showSettings = false; @State private var month = Date(); @State private var selectedDate = Date(); @State private var filter: ShiftFilter = .month; @State private var liveMode: LiveShiftMode?; var body: some View { ScrollView(showsIndicators: false) { VStack(spacing: 18) { ScreenHeader(icon: "flame.fill", title: "Смены", subtitle: "Твой график работы", trailing: AnyView(Button { showSettings = true } label: { Image(systemName: "gearshape.fill").font(.title2).padding(15).background(.ultraThinMaterial, in: Circle()) })); stats; if let liveMode { LiveShiftCard(mode: liveMode, onPause: { self.liveMode = liveMode == .working ? .breakTime : .working }, onFinish: { self.liveMode = nil }) } else { PrimaryButton(title: "Начать смену", icon: "play.fill") { liveMode = .working } }; calendar; SectionTitle(title: "Фильтр", trailing: "\(filteredShifts.count) смен"); Picker("", selection: $filter) { ForEach(ShiftFilter.allCases, id: \.self) { Text($0 == .day ? "День" : $0 == .week ? "Неделя" : $0 == .month ? "Месяц" : "Всё").tag($0) } }.pickerStyle(.segmented).padding(.horizontal, 22); ForEach(filteredShifts) { shift in ShiftRow(shift: shift) }.padding(.horizontal, 22); Button { showAdd = true } label: { Label("Добавить смену на \(selectedDate.shortDate)", systemImage: "plus.circle.fill").font(.headline).frame(maxWidth: .infinity).padding() }.foregroundStyle(.purple).padding(.horizontal, 22) }.padding(.bottom, 16) }.sheet(isPresented: $showAdd) { ShiftEditor(date: selectedDate) }.sheet(isPresented: $showSettings) { ShiftSettingsView() } }
    var filteredShifts: [WorkShift] { let cal = Calendar.current; return store.shifts.filter { s in switch filter { case .day: return cal.isDateInToday(s.date); case .week: return cal.isDate(s.date, equalTo: .now, toGranularity: .weekOfYear); case .month: return cal.isDate(s.date, equalTo: .now, toGranularity: .month); case .all: return true } } }
    var stats: some View { HStack { MetricCard(icon: "clock.fill", value: String(format: "%.1f ч", store.monthlyHours), label: "Часов в месяце", color: .purple); MetricCard(icon: "banknote.fill", value: "\(Int(store.monthlyIncome)) \(store.settings.currency)", label: "Заработок", color: .orange) }.padding(.horizontal, 22) }
    var calendar: some View { GlassCard { VStack(spacing: 12) { HStack { Button { month = Calendar.current.date(byAdding: .month, value: -1, to: month) ?? month } label: { Image(systemName: "chevron.left") }; Spacer(); Text(month.formatted(.dateTime.month(.wide).year())).font(.headline); Spacer(); Button { month = Calendar.current.date(byAdding: .month, value: 1, to: month) ?? month } label: { Image(systemName: "chevron.right") } }.foregroundStyle(.purple); LazyVGrid(columns: Array(repeating: GridItem(.flexible()), count: 7)) { ForEach(Calendar.current.shortStandaloneWeekdaySymbols, id: \.self) { Text($0.prefix(2)).font(.caption.bold()).foregroundStyle(.secondary) }; ForEach(monthDays, id: \.self) { date in let has = store.shifts.contains { Calendar.current.isDate($0.date, inSameDayAs: date) }; Button { selectedDate = date; if has { filter = .day } } label: { VStack(spacing: 4) { Text(date.formatted(.dateTime.day())).frame(width: 34, height: 34).background(Calendar.current.isDate(date, inSameDayAs: selectedDate) ? LinearGradient(colors: [.orange, .pink], startPoint: .top, endPoint: .bottom) : LinearGradient(colors: [.clear, .clear], startPoint: .top, endPoint: .bottom), in: Circle()); if has { Text(store.shifts.first(where: { Calendar.current.isDate($0.date, inSameDayAs: date) })?.emoji ?? "•").font(.caption2) } else { Color.clear.frame(height: 12) } } }.foregroundStyle(.primary) } } } }.padding(.horizontal, 22) }
    var monthDays: [Date] { let cal = Calendar.current; let start = cal.date(from: cal.dateComponents([.year, .month], from: month))!; let weekday = cal.component(.weekday, from: start); let days = cal.range(of: .day, in: .month, for: start)!.map { cal.date(byAdding: .day, value: $0 - 1, to: start)! }; return Array(repeating: start, count: max(0, weekday - 2)) + days }
}
enum LiveShiftMode { case working, breakTime }
struct LiveShiftCard: View { let mode: LiveShiftMode; let onPause: () -> Void; let onFinish: () -> Void; @State private var started = Date(); private var estimatedEnd: Date { started.addingTimeInterval(8 * 3600) }; var body: some View { GlassCard { VStack(spacing: 12) { HStack { Label(mode == .working ? "Смена идёт" : "Перерыв", systemImage: mode == .working ? "flame.fill" : "pause.fill").foregroundStyle(mode == .working ? .orange : .purple); Spacer(); Text(started, style: .timer).font(.title3.monospacedDigit()) }.font(.headline); HStack { VStack(alignment: .leading) { Text("До конца смены").font(.caption).foregroundStyle(.secondary); Text(estimatedEnd, style: .timer).font(.title2.bold()).foregroundStyle(.orange) }; Spacer(); Button(mode == .working ? "Перерыв" : "Продолжить", action: onPause).buttonStyle(.borderedProminent); Button("Завершить", action: onFinish).buttonStyle(.bordered) } } }.padding(.horizontal, 22) } }
struct ShiftRow: View { let shift: WorkShift; var body: some View { HStack { Text(shift.emoji).font(.title2); VStack(alignment: .leading) { Text(shift.name).font(.headline); Text("\(shift.start.formatted(.dateTime.hour().minute())) — \(shift.end.formatted(.dateTime.hour().minute())) · \(shift.duration / 3600, specifier: "%.1f") ч").font(.caption).foregroundStyle(.secondary) }; Spacer(); Text(shift.date.shortDate).font(.caption).foregroundStyle(.secondary) }.padding(14).background(.ultraThinMaterial, in: RoundedRectangle(cornerRadius: 18)) } }
struct ShiftEditor: View { @EnvironmentObject var store: AppStore; @Environment(\.dismiss) var dismiss; let date: Date; @State private var name = "Работа"; @State private var emoji = "🔥"; @State private var start = Date(); @State private var end = Date().addingTimeInterval(8 * 3600); @State private var breaks = 30; @State private var lunch = 30; @State private var manual = false; var body: some View { NavigationStack { Form { Section("Смена") { TextField("Название", text: $name); TextField("Эмодзи", text: $emoji); Toggle("Ручная смена", isOn: $manual) }; Section("Время") { DatePicker("Начало", selection: $start, displayedComponents: .hourAndMinute); DatePicker("Конец", selection: $end, displayedComponents: .hourAndMinute); Stepper("Перерыв: \(breaks) мин", value: $breaks, in: 0...240, step: 5); Stepper("Обед: \(lunch) мин", value: $lunch, in: 0...240, step: 5) } }.navigationTitle("Новая смена").toolbar { ToolbarItem(placement: .cancellationAction) { Button("Отмена") { dismiss() } }; ToolbarItem(placement: .confirmationAction) { Button("Сохранить") { store.shifts.append(WorkShift(name: name, emoji: emoji, date: date, start: start, end: end, breakMinutes: breaks, lunchMinutes: lunch, isManual: manual)); dismiss() } } } } } }
struct ShiftSettingsView: View { @EnvironmentObject var store: AppStore; @Environment(\.dismiss) var dismiss; var body: some View { NavigationStack { Form { Section("Оплата") { Text("Валюту и типы начислений можно менять в настройках приложения.").foregroundStyle(.secondary); Picker("Валюта", selection: $store.settings.currency) { ForEach(["€", "$", "₴", "₽", "£"], id: \.self) { Text($0).tag($0) } }; TextField("Ставка в час", value: $store.settings.hourlyRate, format: .number).keyboardType(.decimalPad); TextField("Бонус за месяц", value: $store.settings.monthlyBonus, format: .number).keyboardType(.decimalPad) }; Section("Подсказка") { Text("Для смены с плавающим временем включи ручной режим — таймер запишет старт, паузы и завершение. Незавершённую смену можно отредактировать позднее.") } }.navigationTitle("Настройки смен").toolbar { Button("Готово") { dismiss() } } } } }
